import 'dart:convert';
import 'package:http/http.dart' as http;
import 'auth_service.dart';
class StockTransferService{StockTransferService._();static final instance=StockTransferService._();static const base=String.fromEnvironment('WMS_API_BASE_URL',defaultValue:'http://localhost:4000/api');Map<String,String> h(){final t=AuthService.instance.session?.accessToken;if(t==null||t.isEmpty)throw Exception('Please login again.');return {'Content-Type':'application/json','Authorization':'Bearer '+t};}String msg(dynamic b)=>b is Map&&b['error'] is Map?(b['error']['message']??'Request failed.').toString():'Request failed.';Future<List<Map<String,dynamic>>> list()async{final r=await http.get(Uri.parse(base+'/stock-transfers'),headers:h());final b=jsonDecode(r.body);if(r.statusCode!=200)throw Exception(msg(b));return (b['data'] as List? ?? []).map((e)=>Map<String,dynamic>.from(e)).toList();}Future<Map<String,dynamic>> detail(String id)async{final r=await http.get(Uri.parse(base+'/stock-transfers/'+id),headers:h());final b=jsonDecode(r.body);if(r.statusCode!=200)throw Exception(msg(b));return Map<String,dynamic>.from(b['data']??{});}
Future<Map<String,dynamic>> create({required String stoNo,required String sourceWarehouseId,required String destinationWarehouseId,required List<Map<String,dynamic>> items,String? remarks})async{return _post('',{'stoNo':stoNo,'sourceWarehouseId':sourceWarehouseId,'destinationWarehouseId':destinationWarehouseId,'items':items,'remarks':remarks});}Future<Map<String,dynamic>> approve(String id)=>_post('/$id/approve',{});Future<Map<String,dynamic>> pick(String id,{required String stoItemId,required String sourceLocationId,required double pickedQty})=>_post('/$id/pick',{'stoItemId':stoItemId,'sourceLocationId':sourceLocationId,'pickedQty':pickedQty});Future<Map<String,dynamic>> receive(String id,{required String stoItemId,required String destinationLocationId,required double receivedQty,String? remarks})=>_post('/$id/receive',{'stoItemId':stoItemId,'destinationLocationId':destinationLocationId,'receivedQty':receivedQty,'remarks':remarks});Future<Map<String,dynamic>> _post(String path,Map<String,dynamic> body)async{final r=await http.post(Uri.parse(base+'/stock-transfers'+path),headers:h(),body:jsonEncode(body));final b=jsonDecode(r.body);if(r.statusCode<200||r.statusCode>=300)throw Exception(msg(b));return Map<String,dynamic>.from(b['data']??{});}}